def is_k_colorable(G, k):
    nodes = list(G.nodes())
    colors = {}
    def backtrack(idx):
        if idx == len(nodes):
            return True
        node = nodes[idx]
        for c in range(k):
            valid = True
            for neighbor in G.neighbors(node):
                if neighbor in colors and colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[node] = c
                if backtrack(idx + 1):
                    return True
                del colors[node]
        return False
    return backtrack(0)

for k in range(1, 10):
    if is_k_colorable(G, k):
        print(f"Chromatic number: {k}")
        print(f"2 <= {k} <= 4: {2 <= k <= 4}")
        break
